INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 13101, 'តាមនិយមន័យ ស្វ៊ីតនៃចំនួនពិត គឺជាអនុគមន៍លេខដែលកំណត់ពី ៖', NULL, '["\\(\\mathbb{Z} \to \\mathbb{Q}\\)", "\\(\\mathbb{N} \to \\mathbb{R}\\)", "\\(\\mathbb{R} \to \\mathbb{R}\\)", "\\(\\mathbb{R} \to \\mathbb{N}\\)"]', 1, NULL, 1, 'mcq', 'ស្វ៊ីតចំនួនពិតគឺជាអនុគមន៍កំណត់ពីសំណុំចំនួនគត់ធម្មជាតិ \(\mathbb{N}\) ទៅសំណុំចំនួនពិត \(\mathbb{R}\)។', 'ស្វ៊ីតចំនួនពិត', 'easy', 1, '11SC', 'ស្វ៊ីតចំនួនពិត', 'ជំពូកទី 1 : ស្វ៊ីតនិងអនុមានរួមគណិតវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 13102, 'ស្វ៊ីតនៃចំនួនការេ \(1, 4, 9, 16, 25, \dots\) មានតួទី \(n\) ស្មើនឹង ៖', NULL, '["\\(a_n = 2n\\)", "\\(a_n = n^3\\)", "\\(a_n = 2^n\\)", "\\(a_n = n^2\\)"]', 3, NULL, 1, 'mcq', 'តួនីមួយៗជាការេនៃចំនួនគត់ធម្មជាតិ 1^2, 2^2, 3^2, ... នាំឱ្យ a_n = n^2។', 'ស្វ៊ីតចំនួនពិត', 'easy', 1, '11SC', 'ស្វ៊ីតចំនួនពិត', 'ជំពូកទី 1 : ស្វ៊ីតនិងអនុមានរួមគណិតវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 13103, 'ស្វ៊ីត \((a_n)\) ជាស្វ៊ីតកើន លុះត្រាតែចំពោះគ្រប់ \(n \in \mathbb{N}\) ៖', NULL, '["\\(a_{n+1} = -a_n\\)", "\\(a_{n+1} \\le a_n\\)", "\\(a_{n+1} \\ge a_n\\)", "\\(a_{n+1} < a_n\\)"]', 2, NULL, 1, 'mcq', 'ស្វ៊ីតកើនកាលណាតួបន្ទាប់ធំជាងឬស្មើនឹងតួមុនជានិច្ច a_{n+1} >= a_n។', 'ស្វ៊ីតចំនួនពិត', 'easy', 1, '11SC', 'ស្វ៊ីតចំនួនពិត', 'ជំពូកទី 1 : ស្វ៊ីតនិងអនុមានរួមគណិតវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 13104, 'ស្វ៊ីត \((a_n)\) មួយត្រូវបានហៅថា «ស្វ៊ីតម៉ូណូតូន» កាលណា ៖', NULL, '["\\(វាជាស្វ៊ីតកើន ឬជាស្វ៊ីតចុះ\\)", "\\(វាមានតួឆ្លាស់សញ្ញា\\)", "\\(វាមានតួទាំងអស់ជាចំនួនវិជ្ជមាន\\)", "\\(វាជាស្វ៊ីតរាប់អស់\\)"]', 0, NULL, 1, 'mcq', 'តាមនិយមន័យ ស្វ៊ីតម៉ូណូតូនគឺជាស្វ៊ីតដែលកើន ឬចុះ។', 'ស្វ៊ីតចំនួនពិត', 'easy', 1, '11SC', 'ស្វ៊ីតចំនួនពិត', 'ជំពូកទី 1 : ស្វ៊ីតនិងអនុមានរួមគណិតវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 13105, 'ក្នុងចំណោមស្វ៊ីតខាងក្រោម តើស្វ៊ីតមួយណាជាស្វ៊ីតរាប់អស់ (Finite Sequence)?', NULL, '["\\(1, 3, 5, 7, 9, 11, 13, 15\\)", "\\(2, 4, 6, 8, \\dots\\)", "\\(1, \frac{1}{2}, \frac{1}{4}, \\dots\\)", "\\(1, 2, 3, 4, 5, \\dots\\)"]', 0, NULL, 1, 'mcq', 'ស្វ៊ីតរាប់អស់គឺជាស្វ៊ីតដែលមានចំនួនតួកំណត់ និងមានតួចុងក្រោយ។', 'ស្វ៊ីតចំនួនពិត', 'easy', 1, '11SC', 'ស្វ៊ីតចំនួនពិត', 'ជំពូកទី 1 : ស្វ៊ីតនិងអនុមានរួមគណិតវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 13106, 'ស្វ៊ីតនៃចំនួនគត់គូ \(2, 4, 6, 8, 10, \dots\) មានតួទី \(n\) ស្មើនឹង ៖', NULL, '["\\(a_n = 2n\\)", "\\(a_n = n^2\\)", "\\(a_n = 2n - 1\\)", "\\(a_n = 2n + 1\\)"]', 0, NULL, 1, 'mcq', 'តួនីមួយៗគឺ 2 គុណនឹង n នាំឱ្យ a_n = 2n។', 'ស្វ៊ីតចំនួនពិត', 'easy', 1, '11SC', 'ស្វ៊ីតចំនួនពិត', 'ជំពូកទី 1 : ស្វ៊ីតនិងអនុមានរួមគណិតវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 13107, 'ស្វ៊ីត \((a_n)\) ជាស្វ៊ីតចុះ លុះត្រាតែចំពោះគ្រប់ \(n \in \mathbb{N}\) ៖', NULL, '["\\(a_{n+1} \\ge a_n\\)", "\\(a_{n+1} = a_n + 1\\)", "\\(a_{n+1} \\le a_n\\)", "\\(a_{n+1} > a_n\\)"]', 2, NULL, 1, 'mcq', 'ស្វ៊ីតចុះកាលណាតួបន្ទាប់តូចជាងឬស្មើនឹងតួមុនជានិច្ច a_{n+1} <= a_n។', 'ស្វ៊ីតចំនួនពិត', 'easy', 1, '11SC', 'ស្វ៊ីតចំនួនពិត', 'ជំពូកទី 1 : ស្វ៊ីតនិងអនុមានរួមគណិតវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 13108, 'គេមានស្វ៊ីត \(a_n = 2n + 1\)។ គណនាតម្លៃនៃតួទី 3 (\(a_3\)) ៖', NULL, '["\\(6\\)", "\\(7\\)", "\\(9\\)", "\\(5\\)"]', 1, NULL, 1, 'mcq', 'ជំនួស n = 3 គេបាន a_3 = 2(3) + 1 = 7។', 'ស្វ៊ីតចំនួនពិត', 'easy', 1, '11SC', 'ស្វ៊ីតចំនួនពិត', 'ជំពូកទី 1 : ស្វ៊ីតនិងអនុមានរួមគណិតវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 13109, 'គេមានស្វ៊ីត \(a_n = 3n - 2\)។ គណនាតម្លៃនៃតួទី 4 (\(a_4\)) ៖', NULL, '["\\(14\\)", "\\(12\\)", "\\(8\\)", "\\(10\\)"]', 3, NULL, 1, 'mcq', 'ជំនួស n = 4 គេបាន a_4 = 3(4) - 2 = 12 - 2 = 10។', 'ស្វ៊ីតចំនួនពិត', 'easy', 1, '11SC', 'ស្វ៊ីតចំនួនពិត', 'ជំពូកទី 1 : ស្វ៊ីតនិងអនុមានរួមគណិតវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 13110, 'គេមានស្វ៊ីត \(a_n = rac{1}{n+1}\)។ គណនាតម្លៃនៃតួទី 3 (\(a_3\)) ៖', NULL, '["\\(\frac{1}{3}\\)", "\\(\frac{3}{4}\\)", "\\(\frac{1}{4}\\)", "\\(\frac{1}{5}\\)"]', 2, NULL, 1, 'mcq', 'ជំនួស n = 3 គេបាន a_3 = 1/(3+1) = 1/4។', 'ស្វ៊ីតចំនួនពិត', 'easy', 1, '11SC', 'ស្វ៊ីតចំនួនពិត', 'ជំពូកទី 1 : ស្វ៊ីតនិងអនុមានរួមគណិតវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 13111, 'គេមានស្វ៊ីត \(a_n = rac{(-1)^{n+1}}{n+1}\)។ គណនាតម្លៃនៃតួទី 4 (\(a_4\)) ៖', NULL, '["\\(-\frac{1}{4}\\)", "\\(\frac{1}{4}\\)", "\\(\frac{1}{5}\\)", "\\(-\frac{1}{5}\\)"]', 3, NULL, 2, 'mcq', 'ជំនួស n = 4 គេបាន a_4 = (-1)^5 / (4+1) = -1/5។', 'ស្វ៊ីតចំនួនពិត', 'medium', 1, '11SC', 'ស្វ៊ីតចំនួនពិត', 'ជំពូកទី 1 : ស្វ៊ីតនិងអនុមានរួមគណិតវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 13112, 'កំណត់តួទី \(n\) នៃស្វ៊ីត \(3, 8, 15, 24, 35, \dots\) ៖', NULL, '["\\(a_n = n(n+1)\\)", "\\(a_n = n^2 + 1\\)", "\\(a_n = 2n^2 + 1\\)", "\\(a_n = n(n+2)\\)"]', 3, NULL, 2, 'mcq', 'តួនីមួយៗគឺ 1(3)=3, 2(4)=8, 3(5)=15, ... នាំឱ្យ a_n = n(n+2) = n^2 + 2n។', 'ស្វ៊ីតចំនួនពិត', 'medium', 1, '11SC', 'ស្វ៊ីតចំនួនពិត', 'ជំពូកទី 1 : ស្វ៊ីតនិងអនុមានរួមគណិតវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 13113, 'ពិនិត្យស្វ៊ីត \(a_n = 5n - 3\)។ គណនាផលសង \(a_{n+1} - a_n\) ដើម្បីបង្ហាញអថេរភាព ៖', NULL, '["\\(0 \\implies \text{ស្វ៊ីតថេរ}\\)", "\\(-5 < 0 \\implies \text{ស្វ៊ីតចុះ}\\)", "\\(5 > 0 \\implies \text{ស្វ៊ីតកើន}\\)", "\\(2 > 0 \\implies \text{ស្វ៊ីតកើន}\\)"]', 2, NULL, 2, 'mcq', 'a_{n+1} - a_n = [5(n+1)-3] - (5n-3) = 5 > 0 នាំឱ្យជាស្វ៊ីតកើន។', 'ស្វ៊ីតចំនួនពិត', 'medium', 1, '11SC', 'ស្វ៊ីតចំនួនពិត', 'ជំពូកទី 1 : ស្វ៊ីតនិងអនុមានរួមគណិតវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 13114, 'ពិនិត្យស្វ៊ីត \(a_n = rac{2n+1}{n+3}\)។ តើស្វ៊ីតនេះជាស្វ៊ីតម៉ូណូតូនដែរឬទេ?', NULL, '["\\(មិនមែនជាស្វ៊ីតម៉ូណូតូនទេ\\)", "\\(ជាស្វ៊ីតថេរ\\)", "\\(ជាស្វ៊ីតម៉ូណូតូនកើន\\)", "\\(ជាស្វ៊ីតម៉ូណូតូនចុះ\\)"]', 2, NULL, 2, 'mcq', 'a_{n+1} - a_n = 5/((n+3)(n+4)) > 0 នាំឱ្យជាស្វ៊ីតកើន ដូចនេះជាស្វ៊ីតម៉ូណូតូន។', 'ស្វ៊ីតចំនួនពិត', 'medium', 1, '11SC', 'ស្វ៊ីតចំនួនពិត', 'ជំពូកទី 1 : ស្វ៊ីតនិងអនុមានរួមគណិតវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 13115, 'គេមានស្វ៊ីត \(a_n = rac{n}{n+1}\)។ គណនាតម្លៃនៃតួទី 5 (\(a_5\)) ៖', NULL, '["\\(\frac{5}{7}\\)", "\\(\frac{6}{5}\\)", "\\(\frac{5}{6}\\)", "\\(\frac{4}{5}\\)"]', 2, NULL, 2, 'mcq', 'ជំនួស n = 5 គេបាន a_5 = 5/(5+1) = 5/6។', 'ស្វ៊ីតចំនួនពិត', 'medium', 1, '11SC', 'ស្វ៊ីតចំនួនពិត', 'ជំពូកទី 1 : ស្វ៊ីតនិងអនុមានរួមគណិតវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 13116, 'ស្វ៊ីតនៃចំនួនគូប \(1, 8, 27, 64, \dots\) មានតួទី 5 ស្មើនឹង ៖', NULL, '["\\(216\\)", "\\(125\\)", "\\(81\\)", "\\(100\\)"]', 1, NULL, 2, 'mcq', 'តួទី 5 គឺ 5^3 = 125។', 'ស្វ៊ីតចំនួនពិត', 'medium', 1, '11SC', 'ស្វ៊ីតចំនួនពិត', 'ជំពូកទី 1 : ស្វ៊ីតនិងអនុមានរួមគណិតវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 13117, 'ពិនិត្យស្វ៊ីត \(b_n = 20 - 4n\)។ តើស្វ៊ីតនេះជាស្វ៊ីតប្រភេទណា?', NULL, '["\\(ស្វ៊ីតថេរ\\)", "\\(មិនមែនស្វ៊ីតម៉ូណូតូន\\)", "\\(ស្វ៊ីតចុះ\\)", "\\(ស្វ៊ីតកើន\\)"]', 2, NULL, 2, 'mcq', 'b_{n+1} - b_n = -4 < 0 នាំឱ្យជាស្វ៊ីតចុះ។', 'ស្វ៊ីតចំនួនពិត', 'medium', 1, '11SC', 'ស្វ៊ីតចំនួនពិត', 'ជំពូកទី 1 : ស្វ៊ីតនិងអនុមានរួមគណិតវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 13118, 'តើស្វ៊ីត \(a_n = (-1)^n rac{1}{n}\) (\(-1, rac{1}{2}, -rac{1}{3}, rac{1}{4}, \dots\)) ជាស្វ៊ីតម៉ូណូតូនដែរឬទេ?', NULL, '["\\(ជាស្វ៊ីតម៉ូណូតូនកើន\\)", "\\(ជាស្វ៊ីតម៉ូណូតូនចុះ\\)", "\\(មិនមែនទេ ព្រោះតួឆ្លាស់សញ្ញា\\)", "\\(ជាស្វ៊ីតថេរ\\)"]', 2, NULL, 2, 'mcq', 'ស្វ៊ីតឆ្លាស់សញ្ញាមិនកើនមិនចុះ ដូច្នេះមិនមែនជាស្វ៊ីតម៉ូណូតូនឡើយ។', 'ស្វ៊ីតចំនួនពិត', 'medium', 1, '11SC', 'ស្វ៊ីតចំនួនពិត', 'ជំពូកទី 1 : ស្វ៊ីតនិងអនុមានរួមគណិតវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 13119, 'កំណត់តួទី \(n\) នៃស្វ៊ីត \(rac{2}{3}, rac{3}{4}, rac{4}{5}, rac{5}{6}, \dots\) ៖', NULL, '["\\(a_n = \frac{n}{n+1}\\)", "\\(a_n = \frac{n+1}{n+3}\\)", "\\(a_n = \frac{n+1}{n+2}\\)", "\\(a_n = \frac{n+2}{n+1}\\)"]', 2, NULL, 2, 'mcq', 'ភាគយកគឺ n+1 ហើយភាគបែងគឺ n+2 នាំឱ្យ a_n = (n+1)/(n+2)។', 'ស្វ៊ីតចំនួនពិត', 'medium', 1, '11SC', 'ស្វ៊ីតចំនួនពិត', 'ជំពូកទី 1 : ស្វ៊ីតនិងអនុមានរួមគណិតវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 13120, 'ពិនិត្យស្វ៊ីត \(c_n = rac{1}{n+3}\) ចំពោះ \(n \ge 1\)។ តើស្វ៊ីតនេះជាស្វ៊ីតប្រភេទណា?', NULL, '["\\(ស្វ៊ីតចុះ\\)", "\\(ស្វ៊ីតថេរ\\)", "\\(ស្វ៊ីតកើន\\)", "\\(ស្វ៊ីតឆ្លាស់\\)"]', 0, NULL, 2, 'mcq', 'c_{n+1} - c_n = 1/(n+4) - 1/(n+3) = -1/((n+3)(n+4)) < 0 នាំឱ្យជាស្វ៊ីតចុះ។', 'ស្វ៊ីតចំនួនពិត', 'medium', 1, '11SC', 'ស្វ៊ីតចំនួនពិត', 'ជំពូកទី 1 : ស្វ៊ីតនិងអនុមានរួមគណិតវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 13121, 'កំណត់តួទី \(n\) នៃស្វ៊ីត \(5, 7, 9, 11, 13, \dots\) ៖', NULL, '["\\(a_n = 2n + 5\\)", "\\(a_n = 2n + 1\\)", "\\(a_n = 2n + 3\\)", "\\(a_n = 3n + 2\\)"]', 2, NULL, 2, 'mcq', 'ផលសង d = 2 នាំឱ្យ a_n = 5 + 2(n-1) = 2n + 3។', 'ស្វ៊ីតចំនួនពិត', 'medium', 1, '11SC', 'ស្វ៊ីតចំនួនពិត', 'ជំពូកទី 1 : ស្វ៊ីតនិងអនុមានរួមគណិតវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 13122, 'កំណត់តួទី \(n\) នៃស្វ៊ីត \(16, 13, 10, 7, 4, \dots\) ៖', NULL, '["\\(a_n = 16 - 3n\\)", "\\(a_n = 19 - 3n\\)", "\\(a_n = 13 - 3n\\)", "\\(a_n = 19 + 3n\\)"]', 1, NULL, 2, 'mcq', 'ផលសង d = -3 នាំឱ្យ a_n = 16 - 3(n-1) = 19 - 3n។', 'ស្វ៊ីតចំនួនពិត', 'medium', 1, '11SC', 'ស្វ៊ីតចំនួនពិត', 'ជំពូកទី 1 : ស្វ៊ីតនិងអនុមានរួមគណិតវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 13123, 'កំណត់តួទី \(n\) នៃស្វ៊ីត \(-3, -1, 1, 3, 5, \dots\) ៖', NULL, '["\\(a_n = 2n - 1\\)", "\\(a_n = 2n - 5\\)", "\\(a_n = 2n - 3\\)", "\\(a_n = 3n - 6\\)"]', 1, NULL, 2, 'mcq', 'ផលសង d = 2 នាំឱ្យ a_n = -3 + 2(n-1) = 2n - 5។', 'ស្វ៊ីតចំនួនពិត', 'medium', 1, '11SC', 'ស្វ៊ីតចំនួនពិត', 'ជំពូកទី 1 : ស្វ៊ីតនិងអនុមានរួមគណិតវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 13124, 'គេមានស្វ៊ីត \(b_n = 2^{-n+2}\)។ គណនាតម្លៃនៃតួទី 3 (\(b_3\)) ៖', NULL, '["\\(1\\)", "\\(\frac{1}{2}\\)", "\\(2\\)", "\\(\frac{1}{4}\\)"]', 1, NULL, 2, 'mcq', 'ជំនួស n = 3 នាំឱ្យ b_3 = 2^{-3+2} = 2^{-1} = 1/2។', 'ស្វ៊ីតចំនួនពិត', 'medium', 1, '11SC', 'ស្វ៊ីតចំនួនពិត', 'ជំពូកទី 1 : ស្វ៊ីតនិងអនុមានរួមគណិតវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 13125, 'ស្វ៊ីតកំណត់ដោយ \(a_1 = 2\) និង \(a_{n+1} = a_n^2\)។ រកតម្លៃនៃតួទី 4 (\(a_4\)) ៖', NULL, '["\\(256\\)", "\\(512\\)", "\\(64\\)", "\\(16\\)"]', 0, NULL, 3, 'mcq', 'a_1 = 2, a_2 = 2^2 = 4, a_3 = 4^2 = 16, a_4 = 16^2 = 256 = 2^{2^3} = 2^8។', 'ស្វ៊ីតចំនួនពិត', 'hard', 1, '11SC', 'ស្វ៊ីតចំនួនពិត', 'ជំពូកទី 1 : ស្វ៊ីតនិងអនុមានរួមគណិតវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 13126, 'ស្វ៊ីត \((a_n)\) កំណត់ដោយ \(a_1 = 1\) និង \(a_{n+1} = a_n^2 + a_n + 1\)។ តើ \((a_n)\) មានអថេរភាពដូចម្តេច?', NULL, '["\\(ជាស្វ៊ីតកើនដាច់ខាត ព្រោះ a_{n+1} - a_n = a_n^2 + 1 > 0\\)", "\\(ជាស្វ៊ីតចុះ ព្រោះ a_{n+1} < a_n\\)", "\\(ជាស្វ៊ីតថេរ\\)", "\\(មិនអាចកំណត់បាន\\)"]', 0, NULL, 3, 'mcq', 'a_{n+1} - a_n = a_n^2 + 1 >= 1 > 0 ចំពោះគ្រប់ n នាំឱ្យវាជាស្វ៊ីតកើនដាច់ខាត។', 'ស្វ៊ីតចំនួនពិត', 'hard', 1, '11SC', 'ស្វ៊ីតចំនួនពិត', 'ជំពូកទី 1 : ស្វ៊ីតនិងអនុមានរួមគណិតវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 13127, 'គេមានស្វ៊ីត \(1, 5, 14, 30, 55, \dots\)។ រកតម្លៃនៃតួបន្ទាប់ (តួទី 6) ៖', NULL, '["\\(85\\)", "\\(90\\)", "\\(96\\)", "\\(91\\)"]', 3, NULL, 3, 'mcq', 'ផលសងតួបន្តបន្ទាប់គឺ 4, 9, 16, 25 (ការេនៃចំនួនគត់)។ ផលសងបន្ទាប់គឺ 6^2 = 36 នាំឱ្យ 55 + 36 = 91។', 'ស្វ៊ីតចំនួនពិត', 'hard', 1, '11SC', 'ស្វ៊ីតចំនួនពិត', 'ជំពូកទី 1 : ស្វ៊ីតនិងអនុមានរួមគណិតវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 13128, 'គេមានស្វ៊ីត \(a_n = rac{2^n}{n}\) ចំពោះ \(n \ge 1\)។ គណនាផលធៀប \(rac{a_{n+1}}{a_n}\) ៖', NULL, '["\\(\frac{2n}{n+1}\\)", "\\(\frac{2}{n+1}\\)", "\\(\frac{2(n+1)}{n}\\)", "\\(\frac{n}{n+1}\\)"]', 0, NULL, 3, 'mcq', 'a_{n+1}/a_n = [2^{n+1}/(n+1)] / [2^n/n] = 2n / (n+1)។', 'ស្វ៊ីតចំនួនពិត', 'hard', 1, '11SC', 'ស្វ៊ីតចំនួនពិត', 'ជំពូកទី 1 : ស្វ៊ីតនិងអនុមានរួមគណិតវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 13129, 'ពិនិត្យស្វ៊ីត \(a_n = rac{n}{n^2+1}\) ចំពោះ \(n \ge 1\)។ តើស្វ៊ីតនេះមានអថេរភាពយ៉ាងដូចម្តេច?', NULL, '["\\(កើនហើយចុះ\\)", "\\(ជាស្វ៊ីតចុះចំពោះគ្រប់ n \\ge 1\\)", "\\(ជាស្វ៊ីតកើនចំពោះគ្រប់ n \\ge 1\\)", "\\(ជាស្វ៊ីតថេរ\\)"]', 1, NULL, 3, 'mcq', 'a_{n+1} - a_n = (1 - n - n^2) / [(n^2+1)((n+1)^2+1)] < 0 ចំពោះគ្រប់ n >= 1 នាំឱ្យជាស្វ៊ីតចុះ។', 'ស្វ៊ីតចំនួនពិត', 'hard', 1, '11SC', 'ស្វ៊ីតចំនួនពិត', 'ជំពូកទី 1 : ស្វ៊ីតនិងអនុមានរួមគណិតវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 13130, 'ស្វ៊ីត \(a_n = n^3 + 4n - 5\)។ គណនាផលសង \(a_{n+1} - a_n\) ៖', NULL, '["\\(3n^2 + 4\\)", "\\(n^2 + 4n\\)", "\\(3n^2 + 3n + 4\\)", "\\(3n^2 + 3n + 5\\)"]', 3, NULL, 3, 'mcq', '(n+1)^3 - n^3 = 3n^2 + 3n + 1 ហើយ 4(n+1) - 4n = 4 នាំឱ្យផលសងស្មើ 3n^2 + 3n + 5 > 0។', 'ស្វ៊ីតចំនួនពិត', 'hard', 1, '11SC', 'ស្វ៊ីតចំនួនពិត', 'ជំពូកទី 1 : ស្វ៊ីតនិងអនុមានរួមគណិតវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 13131, 'ស្វ៊ីត \(a_n = rac{3^n}{n!}\)។ គណនាផលធៀប \(rac{a_{n+1}}{a_n}\) ៖', NULL, '["\\(\frac{3n}{n+1}\\)", "\\(\frac{3}{n+1}\\)", "\\(\frac{1}{n+1}\\)", "\\(\frac{3}{n}\\)"]', 1, NULL, 3, 'mcq', 'a_{n+1}/a_n = [3^{n+1}/(n+1)!] / [3^n/n!] = 3 / (n+1)។', 'ស្វ៊ីតចំនួនពិត', 'hard', 1, '11SC', 'ស្វ៊ីតចំនួនពិត', 'ជំពូកទី 1 : ស្វ៊ីតនិងអនុមានរួមគណិតវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 13132, 'បាល់មួយទម្លាក់ពីកម្ពស់ \(6	ext{ m}\) ហើយពេលធ្លាក់ដល់ដី វាតែងតែលោតឡើងវិញបាន \(rac{2}{3}\) នៃកម្ពស់ធ្លាក់។ គណនាកម្ពស់បាល់លោតឡើងលើកទី 3 ៖', NULL, '["\\(\frac{8}{3}\text{ m}\\)", "\\(4\text{ m}\\)", "\\(\frac{16}{9}\text{ m}\\)", "\\(\frac{32}{27}\text{ m}\\)"]', 2, NULL, 3, 'mcq', 'a_3 = 6 	imes (2/3)^3 = 6 	imes 8/27 = 16/9 m (ប្រហែល 1.78 m)។', 'ស្វ៊ីតចំនួនពិត', 'pisa', 1, '11SC', 'ស្វ៊ីតចំនួនពិត', 'ជំពូកទី 1 : ស្វ៊ីតនិងអនុមានរួមគណិតវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 13133, 'បាក់តេរីមួយប្រភេទបំបែកខ្លួនទ្វេដងរៀងរាល់ 1 ម៉ោង។ ដំបូងមាន 100 កោសិកា។ ចំនួនបាក់តេរីនៅម៉ោងទី \(n\) គឺ \(a_n = 100 	imes 2^n\)។ នៅម៉ោងទី 5 ចំនួនបាក់តេរីកើនដល់ ៖', NULL, '["\\(3\\,200\text{ កោសិកា}\\)", "\\(1\\,600\text{ កោសិកា}\\)", "\\(6\\,400\text{ កោសិកា}\\)", "\\(1\\,000\text{ កោសិកា}\\)"]', 0, NULL, 3, 'mcq', 'a_5 = 100 	imes 2^5 = 100 	imes 32 = 3200 កោសិកា។', 'ស្វ៊ីតចំនួនពិត', 'pisa', 1, '11SC', 'ស្វ៊ីតចំនួនពិត', 'ជំពូកទី 1 : ស្វ៊ីតនិងអនុមានរួមគណិតវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 13134, 'សុខាសន្សំប្រាក់ក្នុងកូនជ្រូក៖ ខែទី 1 សន្សំ 10,000 រៀល ហើយខែនីមួយៗបន្ទាប់សន្សំបន្ថែម 5,000 រៀលលើខែមុន (\(a_n = 5\,000n + 5\,000\))។ នៅខែទី 12 សុខាសន្សំបាន ៖', NULL, '["\\(55\\,000\text{ រៀល}\\)", "\\(65\\,000\text{ រៀល}\\)", "\\(70\\,000\text{ រៀល}\\)", "\\(60\\,000\text{ រៀល}\\)"]', 1, NULL, 3, 'mcq', 'a_{12} = 5000(12) + 5000 = 60000 + 5000 = 65000 រៀល។', 'ស្វ៊ីតចំនួនពិត', 'pisa', 1, '11SC', 'ស្វ៊ីតចំនួនពិត', 'ជំពូកទី 1 : ស្វ៊ីតនិងអនុមានរួមគណិតវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 13135, 'រថយន្តមួយទិញក្នុងតម្លៃ \(20\,000\$\)។ តម្លៃរបស់វាថយចុះ 10% រៀងរាល់ឆ្នាំ (នៅសល់ 90% នៃឆ្នាំមុន)។ តម្លៃរថយន្តនៅចុងឆ្នាំទី 2 គឺ ៖', NULL, '["\\(16\\,000\\$\\)", "\\(16\\,200\\$\\)", "\\(14\\,400\\$\\)", "\\(18\\,000\\$\\)"]', 1, NULL, 3, 'mcq', 'ចុងឆ្នាំទី 1 = 20000 * 0.9 = 18000$។ ចុងឆ្នាំទី 2 = 18000 * 0.9 = 16200$។', 'ស្វ៊ីតចំនួនពិត', 'pisa', 1, '11SC', 'ស្វ៊ីតចំនួនពិត', 'ជំពូកទី 1 : ស្វ៊ីតនិងអនុមានរួមគណិតវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 13136, 'សីតុណ្ហភាពទឹកក្តៅដែលត្រជាក់ចុះក្នុងបន្ទប់កំណត់ដោយ \(T_n = 20 + 60(0.8)^n\ ^\circ	ext{C}\) នៅនាទីទី \(n\)។ នៅនាទីទី 2 សីតុណ្ហភាពទឹកគឺ ៖', NULL, '["\\(68.0^\\circ\text{C}\\)", "\\(50.0^\\circ\text{C}\\)", "\\(58.4^\\circ\text{C}\\)", "\\(48.4^\\circ\text{C}\\)"]', 2, NULL, 3, 'mcq', 'T_2 = 20 + 60(0.8)^2 = 20 + 60(0.64) = 20 + 38.4 = 58.4 องសាសេ។', 'ស្វ៊ីតចំនួនពិត', 'pisa', 1, '11SC', 'ស្វ៊ីតចំនួនពិត', 'ជំពូកទី 1 : ស្វ៊ីតនិងអនុមានរួមគណិតវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 13137, 'គេមានស្វ៊ីត \(a_n = 3n + 2\)។ ចូរគណនាបួនតួដំបូងនៃស្វ៊ីតនេះ (\(a_1, a_2, a_3, a_4\))។', NULL, '[]', 0, NULL, 5, 'writing', 'គណនាតួទី 1: a_1 = 3(1) + 2 = 5 (1 ពិន្ទុ)
គណនាតួទី 2: a_2 = 3(2) + 2 = 8 (1 ពិន្ទុ)
គណនាតួទី 3: a_3 = 3(3) + 2 = 11 (1 ពិន្ទុ)
គណនាតួទី 4: a_4 = 3(4) + 2 = 14 (1 ពិន្ទុ)
សន្និដ្ឋានបួនតួដំបូងនៃស្វ៊ីតគឺ 5, 8, 11, 14 (1 ពិន្ទុ)', 'ស្វ៊ីតចំនួនពិត', 'easy', 0, '11SC', 'ស្វ៊ីតចំនួនពិត', 'ជំពូកទី 1 : ស្វ៊ីតនិងអនុមានរួមគណិតវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 13138, 'កំណត់រូបមន្តតួទី \(n\) (\(a_n\)) នៃស្វ៊ីត \(5, 8, 11, 14, 17, \dots\) ចំពោះគ្រប់ \(n \in \mathbb{N}\)។', NULL, '[]', 0, NULL, 5, 'writing', 'កំណត់តួដំបូង a_1 = 5 (1 ពិន្ទុ)
គណនាផលសងរវាងពីរបន្តបន្ទាប់ d = 8 - 5 = 11 - 8 = 3 (1 ពិន្ទុ)
សរសេររូបមន្តទូទៅ a_n = a_1 + (n - 1)d (1 ពិន្ទុ)
ជំនួសតម្លៃ a_n = 5 + 3(n - 1) (1 ពិន្ទុ)
សម្រួលកន្សោមបាន a_n = 3n + 2 (1 ពិន្ទុ)', 'ស្វ៊ីតចំនួនពិត', 'medium', 0, '11SC', 'ស្វ៊ីតចំនួនពិត', 'ជំពូកទី 1 : ស្វ៊ីតនិងអនុមានរួមគណិតវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 13139, 'បង្ហាញថាស្វ៊ីត \((a_n)\) ដែល \(a_n = rac{1}{n+3}\) ជាស្វ៊ីតចុះចំពោះគ្រប់ \(n \in \mathbb{N}\)។', NULL, '[]', 0, NULL, 5, 'writing', 'កំណត់កន្សោម a_{n+1} = 1/(n+4) (1 ពិន្ទុ)
បង្កើតផលសង a_{n+1} - a_n = 1/(n+4) - 1/(n+3) (1 ពិន្ទុ)
តម្រូវភាគបែងរួម (n+3)(n+4) (1 ពិន្ទុ)
គណនាផលសងបាន (n+3 - (n+4))/((n+3)(n+4)) = -1/((n+3)(n+4)) (1 ពិន្ទុ)
ដោយ -1 < 0 និង (n+3)(n+4) > 0 នាំឱ្យ a_{n+1} - a_n < 0 ដូច្នេះវាជាស្វ៊ីតចុះ (1 ពិន្ទុ)', 'ស្វ៊ីតចំនួនពិត', 'medium', 0, '11SC', 'ស្វ៊ីតចំនួនពិត', 'ជំពូកទី 1 : ស្វ៊ីតនិងអនុមានរួមគណិតវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 13140, 'សិក្សាភាពម៉ូណូតូននៃស្វ៊ីត \(a_n = rac{n}{n+1}\) ចំពោះគ្រប់ \(n \in \mathbb{N}\) តាមវិធីផលធៀប \(rac{a_{n+1}}{a_n}\)។', NULL, '[]', 0, NULL, 5, 'writing', 'បញ្ជាក់ថា a_n = n/(n+1) > 0 ចំពោះគ្រប់ n >= 1 (1 ពិន្ទុ)
សរសេរកន្សោម a_{n+1} = (n+1)/(n+2) > 0 (1 ពិន្ទុ)
បង្កើតផលធៀប a_{n+1}/a_n = [(n+1)/(n+2)] * [(n+1)/n] = (n+1)^2 / (n(n+2)) (1 ពិន្ទុ)
ប្រៀបធៀប (n+1)^2 = n^2 + 2n + 1 > n^2 + 2n នាំឱ្យ a_{n+1}/a_n > 1 (1 ពិន្ទុ)
សន្និដ្ឋានថា a_{n+1} > a_n នាំឱ្យស្វ៊ីតជាស្វ៊ីតកើន ដូចនេះវាជាស្វ៊ីតម៉ូណូតូន (1 ពិន្ទុ)', 'ស្វ៊ីតចំនួនពិត', 'medium', 0, '11SC', 'ស្វ៊ីតចំនួនពិត', 'ជំពូកទី 1 : ស្វ៊ីតនិងអនុមានរួមគណិតវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 13141, 'បង្ហាញថាស្វ៊ីត \((b_n)\) ដែល \(b_n = rac{2n+1}{n+3}\) ជាស្វ៊ីតកើនចំពោះគ្រប់ \(n \in \mathbb{N}\)។', NULL, '[]', 0, NULL, 5, 'writing', 'កំណត់កន្សោម b_{n+1} = (2(n+1)+1)/((n+1)+3) = (2n+3)/(n+4) (1 ពិន្ទុ)
បង្កើតផលសង b_{n+1} - b_n = (2n+3)/(n+4) - (2n+1)/(n+3) (1 ពិន្ទុ)
តម្រូវភាគបែងរួមបាន [(2n+3)(n+3) - (2n+1)(n+4)] / [(n+3)(n+4)] (1 ពិន្ទុ)
ពន្លាតផលគុណភាគយក (2n^2 + 9n + 9) - (2n^2 + 9n + 4) = 5 (1 ពិន្ទុ)
ផលសងស្មើ 5/((n+3)(n+4)) > 0 នាំឱ្យ b_{n+1} > b_n ដូច្នេះជាស្វ៊ីតកើន (1 ពិន្ទុ)', 'ស្វ៊ីតចំនួនពិត', 'medium', 0, '11SC', 'ស្វ៊ីតចំនួនពិត', 'ជំពូកទី 1 : ស្វ៊ីតនិងអនុមានរួមគណិតវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 13142, 'គេមានស្វ៊ីត \((a_n)\) ដែល \(a_1 = 1\) និង \(a_{n+1} = a_n^2 + a_n + 1\)។
ក. បង្ហាញថា \((a_n)\) ជាស្វ៊ីតកើន។
ខ. បង្ហាញថាចំពោះគ្រប់ \(n \in \mathbb{N}\), \(a_n \ge n\)។', NULL, '[]', 0, NULL, 5, 'writing', 'គណនាផលសង a_{n+1} - a_n = a_n^2 + a_n + 1 - a_n = a_n^2 + 1 (1 ពិន្ទុ)
ដោយ a_n^2 >= 0 នាំឱ្យ a_n^2 + 1 >= 1 > 0 នាំឱ្យ a_{n+1} > a_n ដូច្នេះជាស្វ៊ីតកើន (1 ពិន្ទុ)
ផ្ទៀងផ្ទាត់ចំពោះ n = 1: a_1 = 1 >= 1 (ពិត) (1 ពិន្ទុ)
ឧបមាថាពិតដល់ n = k គឺ a_k >= k (1 ពិន្ទុ)
ចំពោះ n = k+1: a_{k+1} = a_k^2 + a_k + 1 >= k^2 + k + 1 > k + 1 នាំឱ្យពិតចំពោះគ្រប់ n (1 ពិន្ទុ)', 'ស្វ៊ីតចំនួនពិត', 'hard', 0, '11SC', 'ស្វ៊ីតចំនួនពិត', 'ជំពូកទី 1 : ស្វ៊ីតនិងអនុមានរួមគណិតវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 13143, 'បង្ហាញថាស្វ៊ីត \(a_n = n^3 + 4n - 5\) ជាស្វ៊ីតកើនដាច់ខាតចំពោះគ្រប់ \(n \in \mathbb{N}\)។', NULL, '[]', 0, NULL, 5, 'writing', 'សរសេរកន្សោម a_{n+1} = (n+1)^3 + 4(n+1) - 5 (1 ពិន្ទុ)
បង្កើតផលសង a_{n+1} - a_n = [(n+1)^3 - n^3] + [4(n+1) - 4n] (1 ពិន្ទុ)
ពន្លាត (n+1)^3 - n^3 = 3n^2 + 3n + 1 (1 ពិន្ទុ)
គណនាផលបូក 3n^2 + 3n + 1 + 4 = 3n^2 + 3n + 5 (1 ពិន្ទុ)
ដោយ n >= 1 នាំឱ្យ 3n^2 + 3n + 5 > 0 ដូច្នេះ a_{n+1} > a_n ជាស្វ៊ីតកើនដាច់ខាត (1 ពិន្ទុ)', 'ស្វ៊ីតចំនួនពិត', 'hard', 0, '11SC', 'ស្វ៊ីតចំនួនពិត', 'ជំពូកទី 1 : ស្វ៊ីតនិងអនុមានរួមគណិតវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 13144, 'គេមានស្វ៊ីតកំណត់ដោយ \(a_1 = 2\) និង \(a_{n+1} = a_n^2\)។ រករូបមន្តតួទី \(n\) (\(a_n\)) នៃស្វ៊ីតនេះ។', NULL, '[]', 0, NULL, 5, 'writing', 'គណនាតួដំបូង a_1 = 2 = 2^{2^0} (1 ពិន្ទុ)
គណនាតួទីពីរ a_2 = a_1^2 = 2^2 = 2^{2^1} = 4 (1 ពិន្ទុ)
គណនាតួទីបី a_3 = a_2^2 = (2^2)^2 = 2^4 = 2^{2^2} = 16 (1 ពិន្ទុ)
គណនាតួទីបួន a_4 = a_3^2 = (2^4)^2 = 2^8 = 2^{2^3} = 256 (1 ពិន្ទុ)
តាមលំនាំ និទស្សន្តគឺ 2^{n-1} ដូច្នេះរូបមន្តតួទី n គឺ a_n = 2^{2^{n-1}} (1 ពិន្ទុ)', 'ស្វ៊ីតចំនួនពិត', 'hard', 0, '11SC', 'ស្វ៊ីតចំនួនពិត', 'ជំពូកទី 1 : ស្វ៊ីតនិងអនុមានរួមគណិតវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 13145, 'បង្ហាញថាស្វ៊ីត \(a_n = rac{2^n}{n}\) ជាស្វ៊ីតកើនចំពោះគ្រប់ \(n \ge 1\)។', NULL, '[]', 0, NULL, 5, 'writing', 'បញ្ជាក់ថាគ្រប់តួ a_n = 2^n / n > 0 ចំពោះគ្រប់ n >= 1 (1 ពិន្ទុ)
បង្កើតផលធៀប a_{n+1} / a_n = [2^{n+1} / (n+1)] / [2^n / n] (1 ពិន្ទុ)
សម្រួលកន្សោមបាន [2^{n+1}/2^n] * [n/(n+1)] = 2n / (n+1) (1 ពិន្ទុ)
ពិនិត្យវិសមភាព 2n - (n+1) = n - 1 >= 0 ចំពោះគ្រប់ n >= 1 នាំឱ្យ 2n >= n+1 (1 ពិន្ទុ)
ដូច្នេះ a_{n+1}/a_n >= 1 នាំឱ្យ a_{n+1} >= a_n ដូចនេះវាជាស្វ៊ីតកើន (1 ពិន្ទុ)', 'ស្វ៊ីតចំនួនពិត', 'hard', 0, '11SC', 'ស្វ៊ីតចំនួនពិត', 'ជំពូកទី 1 : ស្វ៊ីតនិងអនុមានរួមគណិតវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 13146, 'បាល់មួយត្រូវបានទម្លាក់ពីកម្ពស់ \(6	ext{ m}\)។ រាល់ពេលធ្លាក់ដល់ដី វាតែងតែលោតឡើងលើវិញបាន \(rac{2}{3}\) នៃកម្ពស់ធ្លាក់។
ក. កំណត់រូបមន្តកម្ពស់បាល់ពេលលោតឡើងលើកទី \(n\) (\(a_n\))។
ខ. គណនាកម្ពស់បាល់ពេលលោតឡើងលើកទី 3 (\(a_3\))។', NULL, '[]', 0, NULL, 5, 'writing', 'គណនាកម្ពស់លោតលើកទី 1: a_1 = 6 * (2/3) = 4 m (1 ពិន្ទុ)
គណនាកម្ពស់លោតលើកទី 2: a_2 = 4 * (2/3) = 6 * (2/3)^2 = 8/3 m (1 ពិន្ទុ)
សន្និដ្ឋានរូបមន្តកម្ពស់លោតលើកទី n: a_n = 6 * (2/3)^n m (1 ពិន្ទុ)
គណនាកម្ពស់លោតលើកទី 3: a_3 = 6 * (2/3)^3 = 6 * (8/27) = 16/9 m (1 ពិន្ទុ)
បំប្លែងតម្លៃជាប្រភាគ និងទសភាគ: 16/9 m ប្រហែល 1.78 m (1 ពិន្ទុ)', 'ស្វ៊ីតចំនួនពិត', 'pisa', 0, '11SC', 'ស្វ៊ីតចំនួនពិត', 'ជំពូកទី 1 : ស្វ៊ីតនិងអនុមានរួមគណិតវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 13147, 'ទីក្រុងមួយមានប្រជាជនបច្ចុប្បន្ន 500,000 នាក់។ តាមការព្យាករណ៍ ចំនួនប្រជាជនកើនឡើង 2% រៀងរាល់ឆ្នាំ។
ក. សរសេររូបមន្តចំនួនប្រជាជនក្រោយ \(n\) ឆ្នាំ (\(P_n\))។
ខ. គណនាចំនួនប្រជាជនក្រោយរយៈពេល 2 ឆ្នាំ។', NULL, '[]', 0, NULL, 5, 'writing', 'កំណត់កត្តាកំណើនប្រចាំឆ្នាំ: 1 + 2% = 1 + 0.02 = 1.02 (1 ពិន្ទុ)
គណនាចំនួនប្រជាជនក្រោយ 1 ឆ្នាំ: P_1 = 500,000 * 1.02 = 510,000 នាក់ (1 ពិន្ទុ)
សរសេររូបមន្តចំនួនប្រជាជនក្រោយ n ឆ្នាំ: P_n = 500,000 * (1.02)^n នាក់ (1 ពិន្ទុ)
គណនាចំនួនប្រជាជនក្រោយ 2 ឆ្នាំ: P_2 = 500,000 * (1.02)^2 = 520,200 នាក់ (1 ពិន្ទុ)
សន្និដ្ឋានចំនួនប្រជាជនកើនឡើងបាន 20,200 នាក់ក្នុងរយៈពេល 2 ឆ្នាំ (1 ពិន្ទុ)', 'ស្វ៊ីតចំនួនពិត', 'pisa', 0, '11SC', 'ស្វ៊ីតចំនួនពិត', 'ជំពូកទី 1 : ស្វ៊ីតនិងអនុមានរួមគណិតវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 13148, 'ក្រុមកម្មករជីកស្រះមួយ៖ ថ្ងៃទី 1 ជីកបាន \(12	ext{ m}^3\) ថ្ងៃទី 2 បាន \(15	ext{ m}^3\) ថ្ងៃទី 3 បាន \(18	ext{ m}^3\)។
ក. កំណត់រូបមន្តបរិមាណដីជីកបាននៅថ្ងៃទី \(n\) (\(V_n\))។
ខ. គណនាបរិមាណដីដែលជីកបាននៅថ្ងៃទី 10។', NULL, '[]', 0, NULL, 5, 'writing', 'កំណត់បរិមាណដីថ្ងៃដំបូង V_1 = 12 m^3 និងកំណើនប្រចាំថ្ងៃ d = 15 - 12 = 3 m^3 (1 ពិន្ទុ)
សរសេររូបមន្តទូទៅ V_n = V_1 + (n - 1)d (1 ពិន្ទុ)
ជំនួសតម្លៃ V_n = 12 + 3(n - 1) = 3n + 9 m^3 (1 ពិន្ទុ)
គណនាបរិមាណដីនៅថ្ងៃទី 10: V_{10} = 3(10) + 9 = 39 m^3 (1 ពិន្ទុ)
សន្និដ្ឋាននៅថ្ងៃទី 10 ជីកបាន 39 ម៉ែត្រគូប (1 ពិន្ទុ)', 'ស្វ៊ីតចំនួនពិត', 'pisa', 0, '11SC', 'ស្វ៊ីតចំនួនពិត', 'ជំពូកទី 1 : ស្វ៊ីតនិងអនុមានរួមគណិតវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 13149, 'អ្នកជំងឺម្នាក់បានលេបថ្នាំមួយគ្រាប់ទំហំ \(500	ext{ mg}\)។ រៀងរាល់ 4 ម៉ោង បរិមាណថ្នាំក្នុងឈាមថយចុះ 30% (នៅសល់ 70%)។
ក. សរសេររូបមន្តបរិមាណថ្នាំដែលនៅសល់ក្រោយពេលលេបបាន \(4n\) ម៉ោង (\(M_n\))។
ខ. គណនាបរិមាណថ្នាំដែលនៅសល់ក្រោយពេលលេបបាន 8 ម៉ោង។', NULL, '[]', 0, NULL, 5, 'writing', 'កំណត់បរិមាណដើម 500 mg និងអត្រានៅសល់ 1 - 0.30 = 0.70 (1 ពិន្ទុ)
គណនាបរិមាណក្រោយ 4 ម៉ោង (n=1): M_1 = 500 * 0.7 = 350 mg (1 ពិន្ទុ)
សរសេររូបមន្តក្រោយ 4n ម៉ោង: M_n = 500 * (0.7)^n mg (1 ពិន្ទុ)
ក្រោយ 8 ម៉ោងត្រូវនឹង n = 2: M_2 = 500 * (0.7)^2 = 500 * 0.49 = 245 mg (1 ពិន្ទុ)
សន្និដ្ឋានបរិមាណថ្នាំនៅសល់ក្រោយ 8 ម៉ោងគឺ 245 mg (1 ពិន្ទុ)', 'ស្វ៊ីតចំនួនពិត', 'pisa', 0, '11SC', 'ស្វ៊ីតចំនួនពិត', 'ជំពូកទី 1 : ស្វ៊ីតនិងអនុមានរួមគណិតវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 13150, 'កូនឈើមួយដើមពេលដាំមានកម្ពស់ \(1.2	ext{ m}\) ហើយជារៀងរាល់ខែវាលូតលាស់ខ្ពស់ជាងមុន \(0.15	ext{ m}\)។
ក. សរសេររូបមន្តកម្ពស់ដើមឈើនៅខែទី \(n\) (\(H_n\))។
ខ. តើក្រោយពេលដាំបានប៉ុន្មានខែ ទើបដើមឈើនោះមានកម្ពស់ឡើងដល់ \(3.0	ext{ m}\)?', NULL, '[]', 0, NULL, 5, 'writing', 'កំណត់កម្ពស់ដើម H_0 = 1.2 m និងកំណើនប្រចាំខែ 0.15 m (1 ពិន្ទុ)
សរសេររូបមន្តកម្ពស់នៅខែទី n: H_n = 1.2 + 0.15n (m) (1 ពិន្ទុ)
គណនាកម្ពស់ឡើងដល់ 3 m: កំណត់សមីការ 1.2 + 0.15n = 3.0 (1 ពិន្ទុ)
ដោះស្រាយសមីការ: 0.15n = 3.0 - 1.2 = 1.8 នាំឱ្យ n = 1.8 / 0.15 (1 ពិន្ទុ)
គណនាបាន n = 12 ដូច្នេះត្រូវការរយៈពេល 12 ខែ (1 ឆ្នាំ) (1 ពិន្ទុ)', 'ស្វ៊ីតចំនួនពិត', 'pisa', 0, '11SC', 'ស្វ៊ីតចំនួនពិត', 'ជំពូកទី 1 : ស្វ៊ីតនិងអនុមានរួមគណិតវិទ្យា', NULL, 0);
